import { Group, Mesh, PlaneGeometry, BoxGeometry, Color, MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3 } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @param {any} config
 * @param {any} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
	// aliases
	const { Group: ThreeGroup, Mesh: ThreeMesh, PlaneGeometry, Color: ThreeColor, MeshStandardNodeMaterial, MeshBasicNodeMaterial } = ctx.THREE;

	// root group
	const root = new ThreeGroup();

	/*** BACKDROP WITH VERTICAL GRADIENT ***/
	const bgGeom = new PlaneGeometry(7, 6);
	const bgMat = new MeshBasicNodeMaterial();
	// gradient from #0b0b10 to #14141a using uv.y
	bgMat.colorNode = mix(
		vec3(0x0b / 255, 0x0b / 255, 0x10 / 255),
		vec3(0x14 / 255, 0x14 / 255, 0x1a / 255),
		uv().y
	);
	const bgMesh = new ThreeMesh(bgGeom, bgMat);
	bgMesh.position.set(0, 0, -2.5);
	root.add(bgMesh);

	/*** TEXT CONTENT ***/
	const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
	const headlineItem = items[0] ?? { text: '' };
	const headline = ctx.fontAtlas.createText(headlineItem.text ?? headlineItem, {
		fontSize: 68,
		color: '#e8ecf2',
		align: 'left',
	});
	headline.position.set(-1.6, 1.9, 0);
	root.add(headline);

	/*** PLATE SETTINGS ***/
	const PLATE_W = 1.9;
	const PLATE_H = 1.2;
	const PLATE_PITCH = 1.5;
	const PLATE_COUNT = 6;
	const columnOffsetX = 0.9;

	const platesGroup = new ThreeGroup();
	platesGroup.position.set(columnOffsetX, 0, 0);
	root.add(platesGroup);

	// shared geometries
	const plateGeom = new PlaneGeometry(PLATE_W, PLATE_H);
	const frameGeom = new PlaneGeometry(PLATE_W + 0.06, PLATE_H + 0.06); // bevel 0.03 each side
	const accentGeom = new PlaneGeometry(0.03, PLATE_H);

	// shared materials (will be cloned per plate)
	const baseMatProto = new MeshStandardNodeMaterial({
		roughness: 0.6,
		metalness: 0.1,
		clearcoat: 0.1,
	});
	const frameMatProto = new MeshStandardNodeMaterial({
		color: new ThreeColor('#16161d'), // ink
		roughness: 0.5,
		metalness: 0.5,
	});
	const accentMatProto = new MeshStandardNodeMaterial({
		color: new ThreeColor('#ff2a38'),
		emissive: new ThreeColor('#ff2a38'),
		emissiveIntensity: 1.4,
		roughness: 0.6,
		metalness: 0.1,
	});

	// async texture load (synchronous function, texture applied when ready)
	const imageUrl = config.imageUrl || (config.assets && config.assets.imageUrl);
	if (imageUrl) {
		ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
			baseMatProto.map = tex;
			baseMatProto.needsUpdate = true;
		});
	}

	/*** CREATE PLATES ***/
	for (let i = 0; i < PLATE_COUNT; i++) {
		const plate = new ThreeGroup();

		// material clone per plate (to allow future distinct variants)
		const baseMat = baseMatProto.clone();
		const frameMat = frameMatProto.clone();
		const accentMat = accentMatProto.clone();

		// photo plane
		const photoMesh = new ThreeMesh(plateGeom, baseMat);
		photoMesh.position.set(0, 0, 0.001);
		plate.add(photoMesh);

		// frame (bevel)
		const frameMesh = new ThreeMesh(frameGeom, frameMat);
		frameMesh.position.set(0, 0, 0);
		plate.add(frameMesh);

		// left‑edge accent strip
		const accentMesh = new ThreeMesh(accentGeom, accentMat);
		accentMesh.position.set(-PLATE_W / 2 + 0.015, 0, 0.002);
		plate.add(accentMesh);

		// vertical placement
		plate.position.set(0, -i * PLATE_PITCH, 0);
		platesGroup.add(plate);

		/*** CAPTION TEXT FOR THIS PLATE ***/
		const captionItem = items[i + 1] ?? { text: '' };
		const captionText = captionItem.text ?? captionItem;
		const captionObj = ctx.fontAtlas.createText(captionText, {
			fontSize: 18,
			color: '#e8ecf2',
			align: 'left',
		});
		// global X = -1.6 (pinned), Y follows plate Y
		captionObj.position.set(-1.6, -i * PLATE_PITCH, 0.01);
		root.add(captionObj);
	}

	/*** APPLY CINEMATIC PRIMITIVES ***/
	const cleanupFns = [];

	if (Array.isArray(config.cinematicPrimitives)) {
		for (const prim of config.cinematicPrimitives) {
			const handler = ctx.primitives[prim.name];
			if (handler) {
				const result = handler(root, prim.params || {});
				if (result) {
					if (typeof result.cleanup === 'function') cleanupFns.push(result.cleanup);
					if (result.timeline && typeof result.timeline.kill === 'function') cleanupFns.push(() => result.timeline.kill());
				}
			}
		}
	}

	/*** USERDATA & CLEANUP ***/
	root.userData.handlers = {};

	root.userData.cleanup = () => {
		// dispose geometries
		bgGeom.dispose();
		plateGeom.dispose();
		frameGeom.dispose();
		accentGeom.dispose();

		// dispose all materials & textures
		root.traverse((child) => {
			if (child.isMesh) {
				child.geometry.dispose?.();
				if (child.material) {
					if (Array.isArray(child.material)) {
						child.material.forEach((m) => m.dispose?.());
					} else {
						child.material.dispose?.();
					}
				}
			}
		});

		// kill GSAP timelines / primitive cleanups
		cleanupFns.forEach((fn) => {
			try {
				fn();
			} catch (e) {
				/* ignore cleanup errors */
			}
		});
	};

	return root;
}
